// Runs once per email. Builds one canonical view that every layer reads, plus header checks.
// Fields under `x` are in-flight only; Merge Guard strips them before the audit write.
const inp = $input.item.json;
// test flags (guard_bypass, dg_enforce, force_class) exist only on the token-protected red-team webhook
const rt = $('Redteam in').isExecuted && inp.body?.redteam === true ? inp.body : null;

const H = {}; // lower-case header name -> value
let msgId, sender, senderName, subject, bodyText, bodyHtml = '', pdfText = '', pdfPages = 0;

if (rt) {
  msgId      = rt.msg_id ? 'rt-' + rt.msg_id : 'rt-' + rt.id + '-' + Date.now();
  sender     = rt.from || '';
  senderName = rt.from_name || '';
  subject    = rt.subject || '';
  bodyText   = rt.body || '';
  bodyHtml   = rt.body_html || '';
  pdfText    = rt.attachment_text || '';
  pdfPages   = pdfText ? 1 : 0;
  for (const [k, v] of Object.entries(rt.headers || {})) H[k.toLowerCase()] = String(v);
} else {
  const mail = $('Inbox').item.json;
  const pdf  = inp.numpages !== undefined ? inp : null;
  pdfText    = pdf?.text || '';
  pdfPages   = pdf?.numpages || 0;
  msgId      = mail.id;
  sender     = mail.from?.value?.[0]?.address || '';
  senderName = mail.from?.value?.[0]?.name || '';
  subject    = mail.subject || '';
  bodyText   = mail.text || mail.textAsHtml || '';
  bodyHtml   = mail.html || '';
  // Gmail gives "Name: value"; keep the value
  for (const [k, v] of Object.entries(mail.headers || {})) H[k.toLowerCase()] = String(v).replace(/^[^:]*:\s*/, '');
  // mail.headers keeps the LAST copy of a header, which an attacker can add; use Gmail's own (first) verdict
  H['authentication-results'] = mail.gmail_auth_results || '';
}

// --- canonical text: strip invisible characters, decode Unicode tag smuggling, NFKC ---
let invisibleCount = 0, smuggled = '';
const TAGS = /[\u{E0000}-\u{E007F}]/gu;
const INVISIBLE = /[​-‏‪-‮⁠-⁤⁦-⁩﻿­]/g;
const canon = s => {
  s = String(s || '');
  smuggled += [...s.matchAll(/[\u{E0020}-\u{E007E}]/gu)].map(m => String.fromCodePoint(m[0].codePointAt(0) - 0xE0000)).join('');
  const before = [...s].length;
  s = s.replace(TAGS, '').replace(INVISIBLE, '');
  invisibleCount += before - [...s].length;
  return s.normalize('NFKC').replace(/[ \t ]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim();
};
const entities = s => s
  .replace(/&nbsp;/gi, ' ').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'")
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(+d)).replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&amp;/gi, '&');

// --- HTML: split what a human sees from what is hidden by styling ---
const HIDE = /(display\s*:\s*none|visibility\s*:\s*hidden|font-size\s*:\s*[01](\.\d+)?(px|pt|em|rem)?\s*(;|"|'|$)|opacity\s*:\s*0(\.0+)?\s*(;|"|'|$)|(max-)?height\s*:\s*0(px)?\s*(;|"|'|$)|color\s*:\s*(#fff\b|#ffffff\b|white\b|transparent\b))/i;
const VOID = new Set(['img', 'hr', 'meta', 'link', 'input', 'wbr', 'col', 'area', 'base', 'source', 'track', 'param', 'embed']);
const BLOCK = /^(p|div|li|tr|h[1-6]|table|ul|ol|blockquote|section|article|td)$/;
function splitHtml(html) {
  html = String(html || '').replace(/<!--[\s\S]*?-->/g, '').replace(/<(script|style|head|title|template)\b[\s\S]*?<\/\1\s*>/gi, '');
  let shown = '', hidden = '', hiddenDepth = 0;
  const stack = [];
  for (const part of html.split(/(<[^>]+>)/)) {
    if (part.startsWith('<')) {
      const m = part.match(/^<\s*(\/)?\s*([a-z0-9]+)([^>]*)>/i);
      if (!m) continue;
      const [, close, rawTag, attrs] = m;
      const tag = rawTag.toLowerCase();
      if (tag === 'br') { shown += '\n'; continue; }
      if (close) {
        const i = stack.map(s => s.tag).lastIndexOf(tag);
        if (i >= 0) for (const s of stack.splice(i)) if (s.hid) hiddenDepth--;
        if (BLOCK.test(tag)) shown += '\n';
        continue;
      }
      if (VOID.has(tag) || /\/\s*>$/.test(part)) continue;
      const hid = HIDE.test(attrs) || /(^|\s)hidden(\s|=|$)/i.test(attrs);
      stack.push({ tag, hid });
      if (hid) hiddenDepth++;
      if (BLOCK.test(tag)) shown += '\n';
    } else if (hiddenDepth > 0) hidden += entities(part) + ' ';
    else shown += entities(part);
  }
  return { shown, hidden };
}

const plain = canon(bodyText);
const html = bodyHtml ? splitHtml(bodyHtml) : { shown: '', hidden: '' };
const visible = bodyHtml ? canon(html.shown) : plain;
const hiddenText = canon(html.hidden);
const subj = canon(subject);
const pdfView = canon(pdfText).slice(0, 8000);

// text/plain that says something the HTML reader never sees
const words = s => new Set(s.toLowerCase().match(/[a-zЀ-ӿ]{4,}/g) || []);
const shownWords = words(visible);
const plainWords = [...words(plain)];
const extraWords = plainWords.filter(w => !shownWords.has(w));
const plainMismatch = !!bodyHtml && plainWords.length >= 10 && extraWords.length >= 8 && extraWords.length / plainWords.length > 0.3;

// --- what the assistant reads: visible text, no quoted history, no role tokens, capped ---
let view = visible, quoted = '';
const q = view.match(/^(On .{0,200}wrote:|-{2,}\s*Original Message\s*-{2,}|From: .+\n(Sent|Date): .+)/im);
if (q) { quoted = view.slice(q.index); view = view.slice(0, q.index); }
const quotedLines = view.split('\n').filter(l => /^\s*>/.test(l));
if (quotedLines.length) { quoted = quotedLines.join('\n') + '\n' + quoted; view = view.split('\n').filter(l => !/^\s*>/.test(l)).join('\n'); }
const ROLE = /<\|[^|<>]{1,30}\|>/g;
const roleTokens = (view.match(ROLE) || []).length + (subj.match(ROLE) || []).length;
view = view.replace(ROLE, '[token]').trim();
const MAX = 8000;
const truncated = view.length > MAX;
if (truncated) view = view.slice(0, MAX) + '\n[truncated]';

// --- headers: sender authentication, Reply-To redirection, automatic mail ---
// real mail always has Authentication-Results from Gmail; a red-team item is checked only if it sets the header
const authKnown = !rt || "authentication-results" in H;
const ar = (H['authentication-results'] || '').toLowerCase();
const authOf = k => (ar.match(new RegExp('\\b' + k + '=([a-z]+)')) || [])[1] || 'none';
const auth = { spf: authOf('spf'), dkim: authOf('dkim'), dmarc: authOf('dmarc') };
const authFail = authKnown && (auth.dmarc === 'fail' || (auth.spf !== 'pass' && auth.dkim !== 'pass'));
const addrs = s => (String(s || '').match(/[\w.+'-]+@[\w-]+(\.[\w-]+)+/g) || []).map(a => a.toLowerCase());
const replyToMismatch = addrs(H['reply-to']).some(a => a !== sender.toLowerCase());
const autoSubmitted = (H['auto-submitted'] || '').trim().toLowerCase();
const autoReason =
  autoSubmitted && autoSubmitted !== 'no' ? 'auto_submitted'
  : H['list-id'] ? 'mailing_list'
  : /\b(bulk|list|junk)\b/i.test(H['precedence'] || '') ? 'bulk'
  : /^(mailer-daemon|postmaster)@/i.test(sender) || (H['return-path'] || '').trim() === '<>' ? 'bounce'
  : null;

// an attachment arrived but no text came out of it (image-only PDF, other format, extraction error)
const attachmentUnreadable = rt ? rt.attachment_unreadable === true : !!$('Inbox').item.binary?.attachment_0 && !pdfText.trim();
const flags = [];
if (attachmentUnreadable) flags.push('attachment_unreadable');
if (hiddenText) flags.push(`hidden_html:${hiddenText.length}`);
if (invisibleCount) flags.push(`invisible_chars:${invisibleCount}`);
if (smuggled) flags.push('unicode_tag_text');
if (plainMismatch) flags.push('plain_html_mismatch');
if (authFail) flags.push(`auth_fail(spf=${auth.spf},dkim=${auth.dkim},dmarc=${auth.dmarc})`);
if (replyToMismatch) flags.push('reply_to_mismatch');
if (roleTokens) flags.push(`role_tokens:${roleTokens}`);
if (quoted) flags.push('quoted_history_removed');
if (truncated) flags.push('truncated');
if (autoReason) flags.push(autoReason);

const forceEscalate = [authFail && 'sender authentication failed', replyToMismatch && 'Reply-To differs from From',
  plainMismatch && 'plain-text part differs from what the reader sees', attachmentUnreadable && 'attachment could not be read'].filter(Boolean);

const rand = () => Math.random().toString(36).slice(2, 10);
const boundary = `EMAIL_${rand()}${rand()}`.toUpperCase();

const guardView = [
  `Subject: ${subj}`,
  `From: ${canon(senderName)} <${sender}>`,
  `Visible body:\n${view}`,
  quoted && `Quoted earlier messages (removed before the assistant reads the email):\n${quoted.slice(0, 2000)}`,
  hiddenText && `HIDDEN CONTENT (present in the email but invisible to a human reader):\n${hiddenText.slice(0, 3000)}`,
  smuggled && `INVISIBLE UNICODE TEXT (decoded):\n${smuggled.slice(0, 2000)}`,
  plainMismatch && `PLAIN-TEXT PART (differs from what the reader sees):\n${plain.slice(0, 3000)}`,
  pdfView && `Attachment text:\n${pdfView}`,
  flags.length && `Pre-checks: ${flags.join(', ')}`,
].filter(Boolean).join('\n\n');

const urls = [...(view + ' ' + hiddenText + ' ' + smuggled + ' ' + pdfView).matchAll(/https?:\/\/[^\s)>"']+/gi)].map(m => m[0]);
const senderDomain = sender.split('@')[1] || '';
const foreignLinks = urls.filter(u => { try { return !new URL(u).hostname.endsWith(senderDomain); } catch { return true; } });

return {
  json: {
    msg_id: msgId,
    sender: sender,
    sender_name: senderName,
    subject: subject,
    body_text: bodyText,
    body_html: bodyHtml,
    attachments_text: pdfText ? [pdfText] : [],
    pdf_pages: pdfPages,
    pdf_chars: pdfText.length,
    redteam: !!rt,
    dg_enforce: rt ? rt.dg_enforce !== false : true,
    rt_id: rt?.id || null,
    rt_tier: rt?.tier || null,
    rt_category: rt?.category || null,
    rt_target: rt?.target || null,
    rt_canary: rt?.canary || null,
    urls: urls,
    foreign_links: foreignLinks,
    received_at: new Date().toISOString(),
    x: {
      subject: subj,
      sender_line: `${canon(senderName).replace(/[<>]/g, '')} <${sender}>`,
      agent_view: view,
      pdf_view: pdfView,
      guard_view: guardView,
      flags,
      force_escalate: forceEscalate.join('; ') || null,
      guard_bypass: rt?.guard_bypass === true,
      force_class: rt?.guard_bypass === true && rt.force_class ? String(rt.force_class) : null,
      skip_reason: autoReason ? `ignored_${autoReason}` : null,
      boundary,
      canary: `REF-${rand()}`.toUpperCase(),
    },
  },
};

const src = $('Document Guard').item.json;
const g = $input.item.json.output || {};
// `x` holds in-flight views; it is not an audit column
const { dg, x, ...base } = src;

// Fail closed: the email passes Document Guard only if the scan returned a numeric score below 70
// and did not report a scan error. A missing guard, a null score or verdict "error" all block.
const dgScore = typeof dg?.score === 'number' && Number.isFinite(dg.score) ? dg.score : null;
const dgClean = dgScore !== null && dgScore < 70 && dg?.verdict !== 'error';
const pre = (x?.flags || []).join(', ');

return { json: {
  ...base,
  // a missing or non-numeric score is treated as maximum risk (fail-closed)
  risk: Number.isFinite(Number(g.injection_risk)) && g.injection_risk !== null ? Number(g.injection_risk) : 1,
  phishing_risk: Number.isFinite(Number(g.phishing_risk)) && g.phishing_risk !== null ? Number(g.phishing_risk) : 1,
  attack_type: g.attack_type,
  class: x?.force_class || g.class,
  guard_reason: g.reason,
  dg_score: dgScore,
  dg_verdict: dg?.verdict || 'missing',
  dg_signals: [(dg?.provenance?.detectedSignals || []).join(', '), pre && `pre: ${pre}`].filter(Boolean).join(' | '),
  dg_block: base.dg_enforce !== false && !dgClean,
} };

