const base = $('Human override').isExecuted
  ? { ...$('Merge Guard').item.json, class: $('Human override').item.json.class }
  : $('Merge Guard').item.json;
const out  = $input.item.json.output || {};
const x    = $('Normalize').item.json.x || {};

const ALLOWED = {
  support: ['create_ticket', 'draft_reply', 'escalate', 'none'],
  sales:   ['draft_reply', 'escalate', 'none'],
  billing: ['draft_reply', 'escalate', 'none'],
  other:   ['escalate', 'none'],
  spam:    ['escalate', 'none'],
};

const allowed = (ALLOWED[base.class] || ['escalate']).includes(out.action);

// The reply goes back to an untrusted sender: it must not ask for sensitive data,
// and must not carry links, phone numbers, other addresses, markup or the internal marker
const SENSITIVE = /\b(last (four|4|\d+) digits|payment (method|details|info|information)|bank details|card|cvv|cvc|security code|iban|account number|sort code|routing number|password|passcode|one[- ]time (code|password)|otp|pin|passport|id document)s?\b/i;
const reply = String(out.reply_text || '');
const problems = [];
if (out.action === 'draft_reply') {
  // sentences like "please do not send card numbers" are fine; anything else naming these items is not
  const sentences = reply.split(/(?<=[.!?])\s+|\n+/);
  if (sentences.some(s => SENSITIVE.test(s) && !/\b(do not|don't|never|no need to)\b/i.test(s))) problems.push('asks for sensitive data');
  if (/https?:\/\/|www\.|\b[a-z0-9-]+\.(com|net|org|io|ru|xyz|top|info|biz|co|me|app|link|site)\b/i.test(reply)) problems.push('contains a link or domain');
  if (/(\+\d{1,3}[\s.-]?)?\(?\d{2,4}\)?[\s.-]\d{2,4}[\s.-]\d{2,4}/.test(reply)) problems.push('contains a phone number');
  if ((reply.match(/[\w.+-]+@[\w-]+(\.[\w-]+)+/g) || []).some(a => a.toLowerCase() !== String(base.sender).toLowerCase())) problems.push('contains another email address');
  if (x.canary && reply.toUpperCase().includes(x.canary)) problems.push('leaks the internal marker');
  if (/!\[|<[a-z][^>]*>/i.test(reply)) problems.push('contains markup or images');
  if (reply.length > 2000) problems.push('too long');
}
const ok = allowed && problems.length === 0;

return { json: {
  ...base,
  action: ok ? out.action : 'escalate',
  action_requested: out.action,
  blocked_by_allowlist: !ok,
  args: out.args || {},
  reply_text: reply,
  agent_reason: problems.length ? `Blocked reply: ${problems.join(', ')}. ${out.reason || ''}` : out.reason,
  confidence: out.confidence
} };

